app.controller('HourlyRatesController', ['$scope', '$modalInstance', '$q', 'configurationService', 'pivottableService',
  'loggedInUser', 'translations', '$timeout', 'currencySymbol', 'hideRateColumn', 'changed', 'config',
  function ($scope, $modalInstance, $q, configurationService, pivottableService,
    loggedInUser, translations, $timeout, currencySymbol, hideRateColumn, changed, config) {
    $scope.saveCurrencySymbol = function () {
      $scope.loading = true
      changed.changed = true
      if (!$scope.currencySymbol.val) {
        delete $scope.currencySymbol.val
      }
      configurationService.saveConfiguration($scope.currencySymbol, loggedInUser).then(function (config) {
        delete $scope.loading
        $scope.currencySymbol = config
      })
    }

    $scope.saveHideRateColumn = function () {
      $scope.loading = true
      changed.changed = true
      if (!$scope.hideRateColumn.val) {
        delete $scope.hideRateColumn.val
      }
      configurationService.saveConfiguration($scope.hideRateColumn, loggedInUser).then(function (config) {
        delete $scope.loading
        $scope.hideRateColumn = config
      })
    }

    var noUser = { accountId: '', groups: {} }
    var restrictedGroups = config.restrictedGroups.val && config.restrictedGroups.val.filter(group => TimesheetUtils.findByProperty('name', group, loggedInUser.groups.items))
    $scope.restrictedGroups = restrictedGroups && (restrictedGroups.join(',') || 'NONE')
    var isUserAllowed = user => !restrictedGroups ||
      !user.accountId ||
      user.accountId === loggedInUser.accountId ||
      restrictedGroups.filter(group => TimesheetUtils.findByProperty('name', group, user.groups.items)).length
    var sortHourlyRates = hourlyRates => Object.keys(hourlyRates)
      .sort((a, b) => PivotKey.StringComparator($scope.users[a] ? $scope.users[a].displayName : a, $scope.users[b] ? $scope.users[b].displayName : b))
      .reduce((acc, accountId) => {
        acc[accountId] = Object.keys(hourlyRates[accountId])
          .sort()
          .reduce((acc, startDate) => {
            acc[startDate] = hourlyRates[accountId][startDate]
            return acc
          }, {})
        return acc
      }, {})

    $scope.addHourlyRate = function (user, startDate, project, rate) {
      project = project || ''
      if (!user) {
        user = noUser
      }
      if (!user.hasOwnProperty('accountId') || isUserAllowed(user)) {
        var date = (startDate && TimesheetUtils.formatDateForSearch(moment(startDate).toDate())) || ''
        $scope.loading = true
        changed.changed = true
        var groupAccountId = user.hasOwnProperty('accountId') ? user.accountId : 'group:' + user
        configurationService.saveHourlyRate(groupAccountId, date, project, rate).then(() => {
          delete $scope.loading
          $scope.hourlyRateUsers[groupAccountId] = 0
          $scope.hourlyRates[groupAccountId] = $scope.hourlyRates[groupAccountId] || {}
          $scope.hourlyRates[groupAccountId][date] = $scope.hourlyRates[groupAccountId][date] || {}
          $scope.hourlyRates[groupAccountId][date][project] = rate
          if (user.accountId && !$scope.users[user.accountId]) {
            ($scope.users[user.accountId] = user)
          }
          $scope.hourlyRates = sortHourlyRates($scope.hourlyRates)
        })
      } else {
        AP.flag.create({
          title: translations['Denied'],
          body: translations['You can not add rates for this user'],
          type: 'error',
          close: 'auto'
        })
      }
    }

    $scope.removeHourlyRate = function (accountId, startDate, project) {
      project = project || ''
      $scope.loading = true
      changed.changed = true
      configurationService.deleteHourlyRate(accountId, startDate, project).then(function () {
        delete $scope.loading
        delete $scope.hourlyRates[accountId][startDate][project]
        if (!Object.keys($scope.hourlyRates[accountId][startDate]).length) {
          delete $scope.hourlyRates[accountId][startDate]
        }
        if (!Object.keys($scope.hourlyRates[accountId]).length) {
          delete $scope.hourlyRates[accountId]
        }
      })
    }

    $scope.groupUserChange = function (groupAccountId) {
      if (groupAccountId.indexOf('group:') === 0) {
        $scope.paramGroupUserInfo = groupAccountId.substring(6)
      } else {
        pivottableService.getUserInfo(groupAccountId).then(user => { $scope.paramGroupUserInfo = user })
      }
    }

    var $hourlyRates = configurationService.getHourlyRates().then(function (hourlyRates) {
      var promises = []
      Object.keys(hourlyRates).forEach(accountId => {
        $scope.hourlyRateUsers[accountId] = 0
        if (accountId.indexOf('group:') === -1) {
          promises.push(pivottableService.getUserInfo(accountId))
        }
      })
      return $q.all(promises).then(function (users) {
        users.forEach(user => {
          if (isUserAllowed(user)) {
            $scope.users[user.accountId] = user
          } else {
            delete hourlyRates[user.accountId]
          }
        })
        return hourlyRates
      })
    })

    $q.all([$hourlyRates, configurationService.getProjects()]).then(values => {
      var hourlyRates = values[0]
      var projects = values[1]
      $scope.hourlyRates = sortHourlyRates(hourlyRates)
      $scope.allProjects = []
      $scope.projectLabel = {}
      $scope.allProjects.push({ id: undefined, label: translations['Any Project'] })
      $scope.projectLabel[''] = translations['Any Project']
      for (var i = 0; i < projects.length; i++) {
        $scope.allProjects.push({ id: projects[i].key, label: projects[i].name + ' (' + projects[i].key + ')' })
        $scope.projectLabel[projects[i].key] = projects[i].name + ' (' + projects[i].key + ')'
      }
    })

    $scope.cancel = function () {
      $modalInstance.dismiss()
    }

    $scope.currencySymbol = currencySymbol
    $scope.hideRateColumn = hideRateColumn
    $scope.users = {}
    $scope.startDateUsers = {}
    $scope.projectUsers = {}
    $scope.hourlyRateUsers = {}
    $scope.hourlyRate = 0
  }
])
