const getAppEnvId = async (localInstance) => {
  // Fixed environment IDs for Forge app from developer console
  const prodEnvId = '1e298677-4dfa-4966-9486-544a5b279ca7'
  const localEnvId = 'e222406f-5c34-472b-841d-2f2ec52692b0'
  const appEnvId = localInstance ? localEnvId : prodEnvId

  return appEnvId
}

const getForgeUrl = async ({ location, localInstance }) => {
  try {
    const appEnvId = await getAppEnvId(localInstance)
    const params = location.split('?')[1].replace('#!', '&') || null
    const appId = 'd95630c7-9fd4-495d-8988-b55637f4f8e9'

    return `/jira/apps/${appId}/${appEnvId}` + (params ? `?${params}&` : '?') + 'redirectFromOutdatedUrl=true'
  } catch (error) {
    console.error('Error getting Forge URL', error)
    throw new Error('Error getting Forge URL')
  }
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getForgeUrl }
}
