async function getLocale () {
  return new Promise(function (resolve) {
    AP.user.getLocale(resolve)
  })
}

async function getJiraContext () {
  return new Promise(function (resolve) {
    AP.context.getContext(resolve)
  })
}

async function getLocation () {
  return new Promise(function (resolve) {
    AP.getLocation(resolve)
  })
}

async function getCurrentUser () {
  return new Promise(function (resolve) {
    AP.user.getCurrentUser(resolve)
  })
}

async function getToken () {
  return new Promise(function (resolve) {
    AP.context.getToken(resolve)
  })
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getLocale, getJiraContext, getLocation, getCurrentUser, getToken }
}
