      $scope.removeMenuOption = function (key, value, valueUnique) {
        var item = routeParams[key]
        if (key === 'groupByField') {
          trackingService.trackRemovedGrouping($scope, item)
        } else if (key === 'categorizeByField') {
          trackingService.trackRemovedCategorization($scope, item)
        } else if (key === 'moreFields') {
          var option = $scope.moreFieldsOptions.findOption(value, 'isLabel')
          if (option != null) {
            trackingService.trackRemovedColumn($scope, option.id)
          }
        }
        if (angular.isArray(item) && item.length > 1) {
          if (key === 'filterOrProjectId') {
            var option = $scope.filterByOptions.findOption(value, 'isLabel')
            if (option != null) {
              value = option.id
            } else {
              option = $scope.filterByOptions.findOption(value) // deleted
            }
          } else if (key === 'moreFields') {
            var option = $scope.moreFieldsOptions.findOption(value, 'isLabel')
            if (option != null) {
              value = option.id
            }
          }
          item.splice(item.indexOf(value), 1)
          // } else if (item === undefined) {
          //    routeParams[key] = null;
        } else if (key === 'user') {
          var users = (routeParams[key] || loggedInUser.accountId).split(',')
          users.splice(users.indexOf(valueUnique), 1)
          if (!users.length) {
            if ((!routeParams.group || !routeParams.group.length) &&
            ['Timesheet', 'Timespent', 'CostReport', 'PieChart'].indexOf($scope.pivotTableType) >= 0) {
              routeParams.allUsers = true
            }
            delete routeParams[key]
          } else {
            routeParams[key] = users.join(',')
          }
        } else {
          if (key === 'filterOrProjectId') {
            routeParams._allProjects = true
          }
          delete routeParams[key]
        }
        if (['filterOrProjectId', 'worklogFilter', 'moreFields', 'group', 'excludeGroup', 'paramUsersInfo'].indexOf(key) >= 0) {
          $scope.$broadcast(key + 'Updated', routeParams[key])
        }
        saveRouteParams(routeParams)
      }

