if (typeof module === 'object' && module.exports) {
  var CsvView = require('./CsvView')
}

function PdfView (allIssues) {
  this.allIssues = allIssues
}

var pdfUserFieldFormatter = function pdfUserFieldFormatter (field, options) {
  var name = field.displayName || field.name || field.accountId
  return name + (field.emailAddress ? ' <' + field.emailAddress + '>' : '')
}

var pdfKeyFieldFormatter = function pdfKeyFieldFormatter (field, options) {
  var name = field.hasOwnProperty('fields') && field.fields.hasOwnProperty('summary') ? field.fields.summary : field.hasOwnProperty('name') ? field.name : ''
  return name || field.key
}

var getFormattedTime = function (value, config, isElapsedTime) {
  return value ? DrawHelper.getFormattedTime(value, config || {}, isElapsedTime) : ''
}

var amount = function (input) {
  return parseFloat(input && angular.isObject(input) ? input.sum : input || 0)
}
var currency = function (input, symbol) {
  return (symbol || '') + (Math.round(amount(input) * 100) / 100).toLocaleString()
}

var colspanColumns = function (pdfColumns, colspan) {
  for (var i = 0; i < colspan - 1; i++) {
    pdfColumns.push('')
  }
}
PdfView.prototype.fieldValue = CsvView.fieldValueFn(pdfUserFieldFormatter, pdfKeyFieldFormatter, function htmlHoursFormatter (value, options) {
  return getFormattedTime(value, options.jiraConfig, options.isElapsedTime)
})

PdfView.prototype.generate = function (options) {
  var hostBaseUrl = options.hostBaseUrl || ''
  var maxFractionDigits = options.jiraConfig.maxFractionDigits
  var isElapsedTime = options.isElapsedTime = options.pivotTableType === 'IssuePassedTimeByStatus' &&
    !(options.configOptions.workingTimeInStatus.from && options.configOptions.workingTimeInStatus.to)
  // eslint-disable-next-line no-unused-vars
  var prepareLink = function (url, text) {
    return { text: text, link: hostBaseUrl + url }
  }
  var getColumnTitle = function (columnKey) {
    if (columnKey.user) {
      var name = columnKey.user.displayName || columnKey.user.name || columnKey.user.accountId
      return { text: name, link: hostBaseUrl + '/people/' + columnKey.user.accountId, title: columnKey.user.emailAddress }
    } else if (columnKey.date) {
      return moment(columnKey.date).format('DD/MMM')
    } else if (columnKey.weekNumber) {
      return columnKey.weekNumber
    } else if (columnKey.monthKey) {
      return moment(columnKey.keyValue).format('MMM')
    } else {
      if (['TimeTracking', 'TimeEntry', 'IssueTime', 'Timespent', 'CostReport', 'TimeBalance'].indexOf(options.pivotTableType) >= 0) {
        return options.translations[columnKey.keyValue]
      } else {
        return columnKey.keyValue
      }
    }
  }
  var pivotTable
  if (options.pivotTable) {
    pivotTable = options.pivotTable
    if (options.pivotTableType !== 'TimeEntry') {
      options.groupByField = options._groupByField
      options.categorizeByField = options._categorizeByField
    }
  } else {
    pivotTable = PivotTableFactory.createPivotTable(options)
    for (var i in this.allIssues) {
      pivotTable.add(this.allIssues[i])
    }
  }
  pivotTable.showOnce = []
  var columns = pivotTable.sortedColumns()
  var rows = pivotTable.sortedRows()
  var dd = { content: [], styles: { pullRight: { alignment: 'right', lineHeight: 2 } } }
  dd.content.push({ text: options.viewName || 'INVOICE', style: 'pullRight' })
  dd.content.push(' ')
  dd.content.push({ text: options.invoiceHeader, preserveLeadingSpaces: true })
  dd.content.push(' ')
  var table = { headerRows: 1, body: [], widths: ['*', 75, 75, 75] }
  if (!options.compressed) {
    table.widths.push(75)
  }
  dd.content.push({ table: table, layout: 'lightHorizontalLines' })
  var pdfColumns = []
  table.body.push(pdfColumns)
  pdfColumns.push(options.translations['Summary'])
  var hideCommentColumn = options.compressed || options.pivotTableType === 'TimeTracking'
  var option
  for (var i in pivotTable.moreFields) {
    table.widths.push(75)
    var moreField = pivotTable.moreFields[i]
    option = options.moreFieldsOptions.findOption(moreField)
    pdfColumns.push(option ? option.label : moreField)
  }
  if (!hideCommentColumn) {
    pdfColumns.push(options.translations['Work Description'])
  }
  for (var i in columns) {
    pdfColumns.push(getColumnTitle(columns[i].columnKey))
  }
  var hideTotalColumn = ['TimeTracking', 'TimeBalance', 'Timespent', 'CostReport', 'TimeEntry'].indexOf(options.pivotTableType) >= 0
  if (!hideTotalColumn) {
    table.widths.push(75)
    pdfColumns.push(options.translations['Total'])
  }
  var $dd = Promise.resolve(dd)
  rows.forEach(row => {
    $dd = $dd.then(dd => new Promise(resolve => {
      var pdfColumns = []
      var table = dd.content[4].table
      table.body.push(pdfColumns)
      var issue = row.rowKey._issue || row.rowKey.issue || /* groupBy: issue */ row.rowKey.field
      var summary = ''
      if (options.categorizeByField && options.groupByField) {
        var categorizeByFieldValue
        if (options.categorizeByField === 'workeduser') {
          categorizeByFieldValue = pdfUserFieldFormatter(row.rowKey.project, options)
        } else if (['issue', 'project'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = pdfKeyFieldFormatter(row.rowKey.project, options)
        } else if (['workeddate', 'workcreated'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = moment(row.rowKey.project).format(TimesheetUtils.dateTimeFormat)
        } else if (['commentfirstword', 'worklabel', 'workedusergroup'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = row.rowKey._project
        } else if (['workedweek'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = options.translations['Week'] + ' ' + row.rowKey.field.weekNumber
        } else {
          categorizeByFieldValue = this.fieldValue(issue, options.categorizeByField, options)
        }
        summary += categorizeByFieldValue + '\n'
      }
      if (options.groupByField) {
        if (row.categoryRow) {
          pdfColumns.push(summary + (options.showDetailsCount ? ' (' + row.num + ' ' + (options.translations[row.num === 1 ? 'issue_n' : 'issues_n']) + ')' : ''))
        } else {
          var groupByFieldValue
          if (options.groupByField === 'workeduser') {
            groupByFieldValue = pdfUserFieldFormatter(row.rowKey.field, options)
          } else if (['issue', 'parent', 'project'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = pdfKeyFieldFormatter(row.rowKey.field, options)
          } else if (['workeddate', 'workcreated'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = moment(row.rowKey.field).format(TimesheetUtils.dateTimeFormat)
          } else if (['commentfirstword', 'worklabel', 'workedusergroup'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = row.rowKey._field
          } else if (['workedweek'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = options.translations['Week'] + ' ' + row.rowKey.field.weekNumber
          } else {
            groupByFieldValue = this.fieldValue(issue, options.groupByField, options)
          }
          summary += groupByFieldValue
          pdfColumns.push(summary + (options.showDetailsCount ? ' (' + row.num + ' ' + (options.translations[row.num === 1 ? 'issue_n' : 'issues_n']) + ')' : ''))
        }
      } else {
        pdfColumns.push(pdfKeyFieldFormatter(issue, options))
      }
      for (var i in row.moreFields) {
        // FIXME: formatDecimal for time fields
        var fieldName = row.moreFields[i]
        var fieldValue = (row.rowKey._issue && row.rowKey._issue.fields[fieldName]) ||
          (row.rowKey.issue && row.rowKey.issue.fields[fieldName]) ||
          (row.rowKey.field && row.rowKey.field.fields && row.rowKey.field.fields[fieldName])
        if ((fieldName.indexOf('project') < 0 ||
          !options.groupByField ||
          (options.categorizeByField === 'project' && row.rowKey.keyName === 'categoryrow') ||
          (options.groupByField === 'project' && row.rowKey.keyName === 'project'))) {
          pdfColumns.push(this.fieldValue(issue, fieldName, options, null, fieldValue))
        } else {
          pdfColumns.push('')
        }
      }
      if (!hideCommentColumn) {
        pdfColumns.push('')
      }
      for (var i in columns) {
        var columnName = columns[i].columnKey.keyValue
        var entry = row.columns[columnName]
        if (!entry) {
          pdfColumns.push('')
        } else if (columnName === '6progress') {
          var value = entry.value
          if (value.timespent + value.estimate === 0) {
            pdfColumns.push('')
          } else {
            var percents = Math.round(value.timespent * 100 / (value.estimate + value.timespent))
            pdfColumns.push(DrawHelper.formatDecimal(percents, maxFractionDigits) + '%')
          }
        } else if (columnName === '5originalestimateremaining') {
          pdfColumns.push(getFormattedTime(entry.value.value, options.jiraConfig, isElapsedTime))
        } else if (['1started', '3action'].indexOf(columnName) >= 0) {
          pdfColumns.push('')
        } else if (columnName === '62rate') {
          pdfColumns.push(currency(entry, options.configOptions.currencySymbol))
        } else if (columnName === '7cost') {
          pdfColumns.push(currency(entry, options.configOptions.currencySymbol))
        } else {
          pdfColumns.push(getFormattedTime(entry.sum, options.jiraConfig, isElapsedTime) +
                      (options.showDetailsCount ? ' ' + row.columns[columnName].detailsNum + ' ' + getFormattedTime(row.columns[columnName].avg, options.jiraConfig, isElapsedTime) : ''))
        }
      }
      if (!hideTotalColumn) {
        pdfColumns.push(getFormattedTime(row.sum, options.jiraConfig, isElapsedTime) +
                  (options.showDetailsCount ? ' ' + row.detailsNum + ' ' + getFormattedTime(row.avg, options.jiraConfig, isElapsedTime) : ''))
      }
      if (!options.compressed && !row.categoryRow && (options.pivotTableType !== 'TimeTracking' || options.groupByField)) {
        for (var j in row.data) {
          pdfColumns = []
          table.body.push(pdfColumns)
          var detailedRow = row.data[j]
          var detailedIssue = detailedRow.rowKey._issue
          if (detailedIssue) {
            pdfColumns.push(pdfKeyFieldFormatter(detailedIssue, options))
          } else {
            pdfColumns.push('')
          }
          for (var i in row.moreFields) {
            if (row.data[j].rowKey._issue) {
              var key = row.data[j].rowKey._issue.key + '/' + i
              var fieldName = row.moreFields[i]
              if (pivotTable.showOnce.indexOf(key) < 0) {
                var value = row.data[j].rowKey._issue.fields[fieldName]
                if (typeof value === 'number') {
                  pivotTable.showOnce.push(key)
                }
                // FIXME: formatDecimal for time fields
                if (fieldName.indexOf('project') < 0 ||
                  (options.categorizeByField !== 'project' && options.groupByField !== 'project')) {
                  pdfColumns.push(this.fieldValue(row.data[j].rowKey._issue, fieldName, options))
                } else {
                  pdfColumns.push('')
                }
              } else {
                pdfColumns.push('')
              }
            } else {
              pdfColumns.push('')
            }
          }
          if (!hideCommentColumn) {
            pdfColumns.push(detailedRow.worklog && detailedRow.worklog.comment ? detailedRow.worklog.comment.replace(/<([^>]+)>/g, '&lt;$1&gt;') : '')
          }
          for (var i in columns) {
            var columnName = columns[i].columnKey.keyValue
            var value = detailedRow.values[columnName]
            if (columnName === '6progress') {
              if (value.timespent + value.estimate === 0) {
                pdfColumns.push('')
              } else {
                var percents = Math.round(value.timespent * 100 / (value.estimate + value.timespent))
                pdfColumns.push(DrawHelper.formatDecimal(percents, maxFractionDigits))
              }
            } else if (columnName === '5originalestimateremaining') {
              pdfColumns.push(getFormattedTime(value.value, options.jiraConfig, isElapsedTime))
            } else if (['1timeoriginalestimate', '2esttimeremaining', '3timespent', '4diff', '2timespent'].indexOf(columnName) >= 0) {
              pdfColumns.push(getFormattedTime(value, options.jiraConfig, isElapsedTime))
            } else if (columnName === '1started') {
              pdfColumns.push(moment(value).format('LT'))
            } else if (detailedRow.columnKey.keyValue === columnName) {
              pdfColumns.push(getFormattedTime(value, options.jiraConfig, isElapsedTime))
            } else if (columnName === '62rate') {
              pdfColumns.push(currency(value, options.configOptions.currencySymbol))
            } else if (columnName === '7cost') {
              pdfColumns.push(currency(value, options.configOptions.currencySymbol))
            } else {
              pdfColumns.push('')
            }
          }
          if (!hideTotalColumn) {
            pdfColumns.push('')
          }
        }
      }
      resolve(dd)
    }))
  })
  return $dd.then(dd => {
    var pdfColumns = []
    var colspan = 0
    if (options.vat) {
      dd.content[4].table.body.push(pdfColumns)
      if (!options.compressed) {
        colspan++
      }
      pdfColumns.push({ colSpan: colspan,
        text: 'VAT (' + options.vat.rate + '%) (in USD)\nVAT (' + options.vat.rate + '%) (in CZK)'
      })
      colspan += pivotTable.moreFields ? pivotTable.moreFields.length : 0
      colspanColumns(pdfColumns, colspan)
      if (!hideCommentColumn) {
        pdfColumns.push('')
      }
      for (var i in columns) {
        var columnName = columns[i].columnKey.keyValue
        var entry = pivotTable.totals[columnName]
        if (columnName === '62rate') {
          pdfColumns.push('\n' + options.vat.currencyRate)
        } else if (columnName === '7cost') {
          var vat = Math.round(amount(entry) * options.vat.rate) / 100
          pdfColumns.push(currency(vat, options.configOptions.currencySymbol) + '\n' + (Math.round(vat * options.vat.currencyRate * 100) / 100).toLocaleString())
          entry.sum += vat
        } else {
          pdfColumns.push({})
        }
      }
    }
    pdfColumns = []
    dd.content[4].table.body.push(pdfColumns)
    colspan = 0
    if (!options.compressed) {
      colspan++
    }
    pdfColumns.push({ colSpan: colspan,
      text: options.translations['Total']
    })
    colspan += pivotTable.moreFields ? pivotTable.moreFields.length : 0
    colspanColumns(pdfColumns, colspan)
    if (!hideCommentColumn) {
      pdfColumns.push('')
    }
    for (var i in columns) {
      var columnName = columns[i].columnKey.keyValue
      var entry = pivotTable.totals[columnName]
      if (columnName === '6progress') {
        var value = entry.value
        if (value.timespent + value.estimate === 0) {
          pdfColumns.push('')
        } else {
          var percents = Math.round(value.timespent * 100 / (value.estimate + value.timespent))
          pdfColumns.push(DrawHelper.formatDecimal(percents, maxFractionDigits) + '%')
        }
      } else if (columnName === '5originalestimateremaining') {
        pdfColumns.push(getFormattedTime(entry.value.value, options.jiraConfig, isElapsedTime))
      } else if (['1started', '3action'].indexOf(columnName) >= 0) {
        pdfColumns.push('')
      } else if (columnName === '62rate') {
        pdfColumns.push({})
      } else if (columnName === '7cost') {
        pdfColumns.push(currency(entry, options.configOptions.currencySymbol))
      } else {
        pdfColumns.push({})
      }
    }
    if (!hideTotalColumn) {
      pdfColumns.push(getFormattedTime(pivotTable.sum, options.jiraConfig, isElapsedTime) +
              (options.showDetailsCount ? ' ' + pivotTable.detailsNum + ' ' + getFormattedTime(pivotTable.avg, options.jiraConfig, isElapsedTime) : ''))
    }
    colspan += 4 // timespent, rate, cost
    var restrictedProjects = options.restrictedProjects && options.restrictedProjects.join(',')
    if (restrictedProjects) {
      pdfColumns = []
      // dd.content[4].table.body.push(pdfColumns) // not desired for invoice
      pdfColumns.push({ colSpan: colspan,
        text: options.translations['Data is limited by Auditors Roles'] + ' ' + restrictedProjects
      })
      colspanColumns(pdfColumns, colspan)
    }
    var restrictedGroups = options.restrictedGroups && (options.restrictedGroups.join(',') || 'NONE')
    if (restrictedGroups) {
      pdfColumns = []
      // dd.content[4].table.body.push(pdfColumns) // not desired for invoice
      pdfColumns.push({ colSpan: colspan,
        text: options.translations['Data is limited to Restricted Groups'] + ' ' + restrictedGroups
      })
      colspanColumns(pdfColumns, colspan)
    }
    dd.content.push(' ')
    dd.content.push({ text: options.invoiceFooter, preserveLeadingSpaces: true })
    dd.content.push(' ')
    return dd
  })
}

PdfView.prototype.download = function (options) {
  this.generate(options).then(dd => {
    pdfMake.createPdf(dd).download('invoice.pdf')
  })
}

if (typeof module === 'object' && module.exports) {
  module.exports = PdfView
  var PivotTableFactory = require('./PivotTable')
  var DrawHelper = require('../directives/DrawHelper')
  var angular = {
    isObject: o => typeof o === 'object'
  }
}
