const getCloudId = () => {
  return new Promise((resolve) => {
    AP.request({
      url: '/_edge/tenant_info',
      cache: true,
      contentType: 'application/json',
      success: (data) => {
        const parsedData = JSON.parse(data)
        resolve(parsedData.cloudId)
      }
    })
  })
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getCloudId }
}
