if (typeof module === 'object' && module.exports) {
  var CsvView = require('./CsvView')
  var ExcelView = require('./ExcelView')
}

function HtmlView (allIssues, routeParams) {
  this.allIssues = allIssues
  this.routeParams = routeParams
}

var htmlUserFieldFormatter = function htmlUserFieldFormatter (field, options) {
  var name = field.displayName || field.name || field.accountId
  return "<a target='_blank' href='" + options.hostBaseUrl + '/people/' + field.accountId + "' title='" + (field.emailAddress || '') + "'>" + name + '</a>'
}

var htmlKeyFieldFormatter = function htmlKeyFieldFormatter (field, options) {
  var name = field.hasOwnProperty('fields') && field.fields.hasOwnProperty('summary') ? field.fields.summary : ''
  name = name.replace(/'/, '&#39;')
  return "<a target='_blank' href='" + options.hostBaseUrl + '/browse/' + field.key + "' title='" + name + "'>" + field.key + (name ? ' ' + name : '') + '</a>'
}

var htmlProjectFormatter = function htmlKeyFieldFormatter (field, options) {
  var name = field.name.replace(/'/, '&#39;')
  return "<a target='_blank' href='" + options.hostBaseUrl + '/browse/' + field.key + "'>" + name + '</a>'
}

var htmlFormattedTime = function (value, config, isElapsedTime, zeroable) {
  if (value || zeroable) {
    var result = DrawHelper.getFormattedTime(value, config || { locale: 'en_US' }, isElapsedTime, zeroable)
    if (config.timeFormat !== 'pretty') {
      return result.slice(0, -1)
    }
    return result
  } else {
    return ''
  }
}

HtmlView.currency = function (input, symbol) {
  return (symbol || '') + parseFloat(parseFloat(input && typeof input === 'object' ? input.sum : input || 0).toFixed(2)).toLocaleString()
}

HtmlView.prototype.fieldValue = CsvView.fieldValueFn(htmlUserFieldFormatter, htmlKeyFieldFormatter, function htmlHoursFormatter (value, options) {
  return htmlFormattedTime(value, options.jiraConfig, options.isElapsedTime)
})

HtmlView.getDay = function (date) {
  return moment(date).format('DD')
}

HtmlView.getWeek = function (date) {
  return moment(date).format('ddd')
}

HtmlView.getColumnTitle = function (columnKey, options) {
  if (columnKey.user) {
    var name = columnKey.user.displayName || columnKey.user.name || columnKey.user.accountId
    return "<a target='_blank' href='" + options.hostBaseUrl + '/people/' + columnKey.user.accountId + "' title='" + columnKey.user.emailAddress + "'>" + name + '</a>'
  } else if (columnKey.date) {
    return moment(columnKey.date).format('DD/MMM')
  } else if (columnKey.weekNumber) {
    return columnKey.weekNumber
  } else if (columnKey.monthKey) {
    return moment(columnKey.keyValue).format('MMM')
  } else {
    if (['TimeTracking', 'TimeEntry', 'IssueTime', 'Timespent', 'CostReport', 'TimeBalance'].indexOf(options.pivotTableType) >= 0) {
      return options.translations[columnKey.keyValue]
    } else {
      return columnKey.keyValue
    }
  }
}

HtmlView.prototype.generate = function (options) {
  options.hostBaseUrl = options.hostBaseUrl || ''
  var maxFractionDigits = options.jiraConfig.maxFractionDigits
  var isElapsedTime = options.isElapsedTime = options.pivotTableType === 'IssuePassedTimeByStatus' &&
    !(options.configOptions.workingTimeInStatus.from && options.configOptions.workingTimeInStatus.to)
  var prepareLink = function (url, text) {
    return "<a target='_blank' href='" + options.hostBaseUrl + url + "'>" + text + '</a>'
  }
  var pivotTable
  if (options.pivotTable) {
    pivotTable = options.pivotTable
    if (options.pivotTableType !== 'TimeEntry') {
      options.groupByField = options._groupByField
      options.categorizeByField = options._categorizeByField
    }
  } else {
    pivotTable = PivotTableFactory.createPivotTable(options)
    for (var i in this.allIssues) {
      pivotTable.add(this.allIssues[i])
    }
    pivotTable.postProcessPivotTable(options)
  }
  pivotTable.showOnce = []
  var columns = pivotTable.sortedColumns()
  var rows = pivotTable.sortedRows()
  var excel = '<style>\n'
  excel += '<!--br\n'
  excel += '    {mso-data-placement:same-cell;}\n'
  excel += '<!--table\n'
  var separators = Intl.NumberFormat(options.jiraConfig.locale.replace('_', '-')).formatToParts(1234.5)
  var decimalSeparator = separators.find(separator => separator.type === 'decimal')
  excel += decimalSeparator ? '    {mso-displayed-decimal-separator:"\\' + decimalSeparator.value + '";' : ''
  var groupSeparator = separators.find(separator => separator.type === 'group')
  excel += (groupSeparator ? (decimalSeparator ? '\n     ' : '    {') + 'mso-displayed-thousand-separator:"\\' + groupSeparator.value + '";' : '') + '}\n'
  excel += '-->\n'
  excel += '</style>\n'
  if (options.gadgetSummary) {
    excel += '<div>\n'
    options.gadgetSummary.forEach(option => {
      excel += '<span' + (options.styleClass ? ' class="' + options.styleClass + '"' : '') + '>' + option.text + '</span>\n'
    })
    excel += '<a class="external-link-square" title="' + options.translations['Open report page for other options and excel export'] + '" href="' + options.hostBaseUrl + '/plugins/servlet/ac/jira-timesheet-plugin/timereports#!' + options.reportParams + '" target="_blank">&#x279a;</a>\n'
    excel += '</div>\n'
  }
  excel += '<table class="aui aui-table-list">\n'
  excel += " <tr class='rowFooter'>\n"
  if (options.categorizeByField && options.groupByField) {
    excel += "    <th class='nav border total'>" + (options.categorizeByFieldOption ? options.categorizeByFieldOption.label : options.categorizeByField) + '</th>\n'
  }
  if (options.groupByField) {
    excel += "    <th class='nav border total'>" + (options.groupByFieldOption ? options.groupByFieldOption.label : options.groupByField) + '</th>\n'
  }
  var hideCommentColumn = options.compressed || options.pivotTableType === 'TimeTracking'
  if (!options.groupByField || (options.groupByField && !options.compressed) || options.groupByField === 'issue') {
    excel += "    <th class='nav border total'>" + options.translations['Issue Type'] + '</th>\n'
    excel += "    <th class='nav border total'>" + options.translations['Parent'] + '</th>\n'
    excel += "    <th class='nav border total'>" + options.translations['Key'] + '</th>\n'
    excel += "    <th class='nav border total'>" + options.translations['Summary'] + '</th>\n'
    excel += "    <th class='nav border total'>" + options.translations['Priority'] + '</th>\n'
  }
  var option
  for (var i in pivotTable.moreFields) {
    var moreField = pivotTable.moreFields[i]
    option = options.moreFieldsOptions.findOption(moreField)
    excel += "    <th class='nav border total'>" + (option ? option.label : moreField) + '</th>\n'
  }
  if (!hideCommentColumn) {
    excel += "    <th class='nav border total'>" + options.translations['Work Description'] + '</th>\n'
  }
  for (var i in columns) {
    var columnTitle = HtmlView.getColumnTitle(columns[i].columnKey, options)
    if (['TimeTracking', 'TimeEntry', 'Timespent', 'CostReport', 'TimeBalance'].indexOf(options.pivotTableType) >= 0 &&
        ['1timeoriginalestimate', '12estimate', '2esttimeremaining', '4diff', '5originalestimateremaining', '2timespent', '3timespent'].indexOf(columns[i].columnKey.keyValue) >= 0) {
      var timeFormat = options.configOptions.durationType || 'h'
      columnTitle += ' (' + timeFormat + ')'
    }
    excel += "    <th class='nav border total'>" + columnTitle + '</th>\n'
  }
  var hideTotalColumn = ['TimeTracking', 'TimeBalance', 'CostReport', 'TimeEntry'].indexOf(options.pivotTableType) >= 0 ||
    (options.pivotTableType === 'Timespent' && !options.pivotByField)
  if (!hideTotalColumn) {
    excel += "    <th class='nav border total'>" + options.translations['Total'] + '</th>\n'
  }
  excel += '  </tr>\n'
  var $excel = Promise.resolve(excel)
  rows.forEach(row => {
    $excel = $excel.then(excel => new Promise(resolve => {
      excel += '  <tr>\n'
      var issue = row.rowKey._issue || row.rowKey.issue || /* groupBy: issue */ row.rowKey.field
      if (options.categorizeByField && options.groupByField) {
        var categorizeByFieldValue
        if (options.categorizeByField === 'workeduser') {
          categorizeByFieldValue = htmlUserFieldFormatter(row.rowKey.project, options)
        } else if (['issue', 'parent'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = htmlKeyFieldFormatter(row.rowKey.project, options)
        } else if (options.categorizeByField === 'project') {
          categorizeByFieldValue = htmlProjectFormatter(row.rowKey.project, options)
        } else if (['workeddate', 'workcreated'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = moment(row.rowKey.project).format(TimesheetUtils.dateTimeFormat)
        } else if (['commentfirstword', 'worklabel', 'workedusergroup'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = row.rowKey._project
        } else if (['workedweek'].indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = options.translations['Week'] + ' ' + row.rowKey.field.weekNumber
        } else if (row.moreFields && row.moreFields.indexOf(options.categorizeByField) >= 0) {
          categorizeByFieldValue = row.rowKey._project // see PivotRow.prototype.add#line 41
        } else {
          categorizeByFieldValue = this.fieldValue(issue, options.categorizeByFieldObject, options, null, row.rowKey.project)
        }
        excel += "    <td class='nav border'>" + categorizeByFieldValue + '</td>\n'
      }
      if (options.groupByField) {
        if (row.categoryRow) {
          excel += "    <td class='nav border'>" + (options.showDetailsCount ? ' (' + row.num + ' ' + (options.translations[row.num === 1 ? 'issue_n' : 'issues_n']) + ')' : '') + '</td>\n'
        } else {
          var groupByFieldValue
          if (options.groupByField === 'workeduser') {
            groupByFieldValue = htmlUserFieldFormatter(row.rowKey.field, options)
          } else if (['issue', 'parent'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = htmlKeyFieldFormatter(row.rowKey.field, options)
          } else if (options.groupByField === 'project') {
            groupByFieldValue = htmlProjectFormatter(row.rowKey.field, options)
          } else if (['workeddate', 'workcreated'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = moment(row.rowKey.field).format(TimesheetUtils.dateTimeFormat)
          } else if (['commentfirstword', 'worklabel', 'workedusergroup'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = row.rowKey._field
          } else if (['workedweek'].indexOf(options.groupByField) >= 0) {
            groupByFieldValue = options.translations['Week'] + ' ' + row.rowKey.field.weekNumber
          } else if (row.moreFields && row.moreFields.indexOf(options.groupByField) >= 0) {
            groupByFieldValue = row.rowKey._field // see PivotRow.prototype.add#line 41
          } else {
            groupByFieldValue = this.fieldValue(issue, options.groupByFieldObject, options, null, row.rowKey.field)
          }
          excel += "    <td class='nav border'>" + groupByFieldValue + (options.showDetailsCount ? ' (' + row.num + ' ' + (options.translations[row.num === 1 ? 'issue_n' : 'issues_n']) + ')' : '') + '</td>\n'
        }
      }
      if (row.rowKey.issue || options.groupByField === 'issue') {
        excel += "    <td class='nav border'>" + issue.fields.issuetype.name + '</td>\n'
        excel += "    <td class='nav border' nowrap>" + (issue.fields.parent ? prepareLink('/browse/' + issue.fields.parent.key, issue.fields.parent.key) : '') + '</td>\n'
        excel += "    <td class='nav border' nowrap>" + prepareLink('/browse/' + issue.key, issue.key) + '</td>\n'
        excel += "    <td class='nav border'>" + prepareLink('/browse/' + issue.key, issue.fields.summary) + '</td>\n'
        excel += "    <td class='nav border'>" + this.fieldValue(issue, 'priority', options) + '</td>\n'
      } else if (!options.compressed) { // groupByField
        excel += TimesheetUtils.repeat("    <td class='nav border'>&nbsp;</td>\n", 5)
      }
      for (var i in row.moreFields) {
        // FIXME: formatDecimal for time fields
        var fieldName = row.moreFields[i]
        var fieldValue = (row.rowKey._issue && row.rowKey._issue.fields[fieldName]) ||
          (row.rowKey.issue && row.rowKey.issue.fields[fieldName]) ||
          (row.rowKey.field && row.rowKey.field.fields && row.rowKey.field.fields[fieldName])
        if ((fieldName.indexOf('project') < 0 ||
          !options.groupByField ||
          (['project', 'issue'].indexOf(options.categorizeByField) >= 0 && row.rowKey.keyName === 'categoryrow') ||
          (options.groupByField === 'project' && row.rowKey.keyName === 'project') ||
          options.groupByField === 'issue')) {
          excel += "    <td class='nav border'>" + this.fieldValue(issue, fieldName, options, null, fieldValue) + '</td>\n'
        } else {
          excel += "    <td class='nav border'>" + '</td>\n'
        }
      }
      if (!hideCommentColumn) {
        excel += "    <td class='nav border'>&nbsp</td>\n"
      }
      for (var i in columns) {
        var columnName = columns[i].columnKey.keyValue
        var entry = row.columns[columnName]
        if (!entry) {
          excel += "    <td class='nav border'></td>\n"
        } else if (columnName === '6progress') {
          var value = entry.value
          if (value.timespent + value.estimate === 0) {
            excel += "    <td class='nav border'></td>\n"
          } else {
            var percents = Math.round(value.timespent * 100 / (value.estimate + value.timespent))
            excel += "    <td class='nav border'>" + DrawHelper.formatDecimal(percents, maxFractionDigits, options.jiraConfig.locale) + '%</td>\n'
          }
        } else if (columnName === '5originalestimateremaining') {
          excel += "    <td class='nav border'>" + htmlFormattedTime(entry.value.value, options.jiraConfig, isElapsedTime) + '</td>\n'
        } else if (['1started', '3action'].indexOf(columnName) >= 0) {
          excel += "    <td class='nav border'></td>\n"
        } else if (['62rate', '7cost'].indexOf(columnName) >= 0) {
          excel += "    <td class='nav border'>" + HtmlView.currency(entry, options.configOptions.currencySymbol) + '</td>\n'
        } else {
          excel += "    <td class='nav border'>" + htmlFormattedTime(entry.sum, options.jiraConfig, isElapsedTime) +
                      (options.showDetailsCount && options.pivotTableType !== 'Timesheet' ? ' ' + row.columns[columnName].detailsNum + ' ' + htmlFormattedTime(row.columns[columnName].avg, options.jiraConfig, isElapsedTime) : '') + '</td>\n'
        }
      }
      if (!hideTotalColumn) {
        excel += "    <td class='nav border total'>" + htmlFormattedTime(row.sum, options.jiraConfig, isElapsedTime) +
                  (options.showDetailsCount && options.pivotTableType !== 'Timesheet' ? ' ' + row.detailsNum + ' ' + htmlFormattedTime(row.avg, options.jiraConfig, isElapsedTime) : '') + '</td>\n'
      }
      excel += '  </tr>\n'
      if (!options.compressed && !row.categoryRow && (options.pivotTableType !== 'TimeTracking' || options.groupByField)) {
        for (var j in row.data) {
          excel += '  <tr>\n'
          if (options.categorizeByField && options.groupByField) {
            excel += "    <td class='nav border'>&nbsp;</td>\n"
          }
          if (options.groupByField) {
            excel += "    <td class='nav border'>&nbsp;</td>\n"
          }
          var detailedRow = row.data[j]
          var detailedIssue = detailedRow.rowKey._issue
          if (detailedIssue) {
            excel += "    <td class='nav border'>" + detailedIssue.fields.issuetype.name + '</td>\n'
            excel += "    <td class='nav border'>" + (detailedIssue.fields.parent ? prepareLink('/browse/' + detailedIssue.fields.parent.key, detailedIssue.fields.parent.key) : '') + '</td>\n'
            excel += "    <td class='nav border'>" + prepareLink('/browse/' + detailedIssue.key, detailedIssue.key) + '</td>\n'
            excel += "    <td class='nav border'>" + prepareLink('/browse/' + detailedIssue.key, detailedIssue.fields.summary) + '</td>\n'
            excel += "    <td class='nav border'>" + this.fieldValue(detailedIssue, 'priority', options) + '</td>\n'
          } else {
            excel += TimesheetUtils.repeat("    <td class='nav border'>&nbsp;</td>\n", 5)
          }
          for (var i in row.moreFields) {
            if (row.data[j].rowKey._issue) {
              var key = row.data[j].rowKey._issue.key + '/' + i
              if (pivotTable.showOnce.indexOf(key) < 0) {
                var value = row.data[j].rowKey._issue.fields[row.moreFields[i]]
                if (typeof value === 'number') {
                  pivotTable.showOnce.push(key)
                }
                // FIXME: formatDecimal for time fields
                if (fieldName.indexOf('project') < 0 ||
                  (options.categorizeByField !== 'project' && options.groupByField !== 'project')) {
                  excel += "    <td class='nav border'>" + this.fieldValue(row.data[j].rowKey._issue, row.moreFields[i], options) + '</td>\n'
                } else {
                  excel += "    <td class='nav border'>" + '</td>\n'
                }
              } else {
                excel += "    <td class='nav border'>&nbsp;</td>\n"
              }
            } else {
              excel += "    <td class='nav border'>&nbsp;</td>\n"
            }
          }
          if (!hideCommentColumn) {
            excel += "    <td class='nav border'>" +
              (detailedRow.worklog && detailedRow.worklog._issue
                ? prepareLink('/browse/' + detailedRow.worklog._issue.key,
                  detailedRow.worklog._issue.key + ' ' + (detailedRow.worklog.comment ? detailedRow.worklog.comment.replace(/<([^>]+)>/g, '&lt;$1&gt;') : ''))
                : (detailedRow.worklog && detailedRow.worklog.comment ? detailedRow.worklog.comment.replace(/<([^>]+)>/g, '&lt;$1&gt;') : '')) + '</td>\n'
          }
          for (var i in columns) {
            var columnName = columns[i].columnKey.keyValue
            var value = detailedRow.values[columnName]
            if (columnName === '6progress') {
              if (value.timespent + value.estimate === 0) {
                excel += "    <td class='nav border'></td>\n"
              } else {
                var percents = Math.round(value.timespent * 100 / (value.estimate + value.timespent))
                excel += "    <td class='nav border'>" + DrawHelper.formatDecimal(percents, maxFractionDigits, options.jiraConfig.locale) + '%</td>\n'
              }
            } else if (columnName === '5originalestimateremaining') {
              excel += "    <td class='nav border'>" + htmlFormattedTime(value.value, options.jiraConfig, isElapsedTime) + '</td>\n'
            } else if (['1timeoriginalestimate', '2esttimeremaining', '3timespent', '4diff', '2timespent'].indexOf(columnName) >= 0) {
              excel += "    <td class='nav border'>" + htmlFormattedTime(value, options.jiraConfig, isElapsedTime) + '</td>\n'
            } else if (columnName === '1started') {
              excel += "    <td class='nav border'>" + moment(value).format('LT') + '</td>\n'
            } else if (detailedRow.columnKey.keyValue === columnName) {
              excel += "    <td class='nav border'>" + htmlFormattedTime(value, options.jiraConfig, isElapsedTime, 'zeroable') + '</td>\n'
            } else if (['62rate', '7cost'].indexOf(columnName) >= 0) {
              excel += "    <td class='nav border'>" + HtmlView.currency(value, options.configOptions.currencySymbol) + '</td>\n'
            } else {
              excel += "    <td class='nav border'>&nbsp;</td>\n"
            }
          }
          if (!hideTotalColumn) {
            excel += "    <td class='nav border'>&nbsp;</td>\n"
          }
          excel += '  </tr>\n'
        }
      }
      resolve(excel)
    }))
  })
  return $excel.then(excel => {
    excel += "  <tr class='rowFooter'>\n"
    var colspan = 0
    if (options.categorizeByField && options.groupByField) {
      colspan++
    }
    if (options.groupByField) {
      colspan++
    }
    if (!options.groupByField || !options.compressed || options.groupByField === 'issue') {
      colspan += 5
    }
    excel += "    <th class='nav border total' colspan=" + colspan + '>' + options.translations['Total'] +
      (options.showDetailsCount ? ' (' + pivotTable.num + ' ' + options.translations[pivotTable.num === 1 ? 'issue_n' : 'issues_n'] + ')' : '') + '</th>\n'
    for (var i in pivotTable.moreFields) {
      // FIXME: formatDecimal for time fields
      excel += "    <th class='nav border total'>" + this.fieldValue({ fields: pivotTable.fieldTotals }, pivotTable.moreFields[i], options) + '</th>\n'
    }
    if (!hideCommentColumn) {
      excel += "    <th class='nav border total'>&nbsp;</th>\n"
    }
    for (var i in columns) {
      var columnName = columns[i].columnKey.keyValue
      var entry = pivotTable.totals[columnName]
      if (columnName === '6progress') {
        var value = entry.value
        if (value.timespent + value.estimate === 0) {
          excel += "    <td class='nav border total'></td>\n"
        } else {
          var percents = Math.round(value.timespent * 100 / (value.estimate + value.timespent))
          excel += "    <th class='nav border total'>" + DrawHelper.formatDecimal(percents, maxFractionDigits, options.jiraConfig.locale) + '%</th>\n'
        }
      } else if (columnName === '5originalestimateremaining') {
        excel += "    <th class='nav border total'>" + htmlFormattedTime(entry.value.value, options.jiraConfig, isElapsedTime) + '</th>\n'
      } else if (['1started', '3action'].indexOf(columnName) >= 0) {
        excel += "    <th class='nav border total'></th>\n"
      } else if (['62rate', '7cost'].indexOf(columnName) >= 0) {
        excel += "    <th class='nav border total'>" + HtmlView.currency(entry, options.configOptions.currencySymbol) + '</th>\n'
      } else {
        excel += "    <th class='nav border total'>" + htmlFormattedTime(entry.sum, options.jiraConfig, isElapsedTime) +
                  (options.showDetailsCount && options.pivotTableType !== 'Timesheet' ? ' ' + entry.detailsNum + ' ' + htmlFormattedTime(entry.avg, options.jiraConfig, isElapsedTime) : '') + '</th>\n'
      }
    }
    if (!hideTotalColumn) {
      excel += "    <th class='nav border total'>" + htmlFormattedTime(pivotTable.sum, options.jiraConfig, isElapsedTime) +
              (options.showDetailsCount && options.pivotTableType !== 'Timesheet' ? ' ' + pivotTable.detailsNum + ' ' + htmlFormattedTime(pivotTable.avg, options.jiraConfig, isElapsedTime) : '') + '</th>\n'
    }
    excel += '  </tr>\n'
    var restrictedProjects = options.restrictedProjects && options.restrictedProjects.join(',')
    if (restrictedProjects) {
      excel += "<tr><td class='nav border total' colspan=" + colspan + '>' + options.translations['Data is limited by Auditors Roles'] + ' ' + restrictedProjects + '</td></tr>'
    }
    var restrictedGroups = options.restrictedGroups && (options.restrictedGroups.join(',') || 'NONE')
    if (restrictedGroups) {
      excel += "<tr><td class='nav border total' colspan=" + colspan + '>' + options.translations['Data is limited to Restricted Groups'] + ' ' + restrictedGroups + '</td></tr>'
    }
    excel += '</table>\n'
    return excel
  })
}

HtmlView.prototype.download = ExcelView.prototype.download

if (typeof module === 'object' && module.exports) {
  module.exports = HtmlView
  var PivotTableFactory = require('./PivotTable')
  var TimesheetUtils = require('../../timesheetUtils')
  var DrawHelper = require('../../app/directives/DrawHelper')
  var moment = require('moment-timezone')
}
