const getJiraConfig = () => {
  const AP = window.RA || window.AP
  return new Promise((resolve) => {
    AP.request({
      url: '/rest/atlassian-connect/1/addons/jira-timesheet-plugin/properties/configuration',
      cache: true,
      contentType: 'application/json',
      success: (data) => {
        const parsedData = JSON.parse(data)
        resolve(parsedData)
      },
      error: function (error) {
        console.log('Error getting Jira configuration', error)
        resolve(null)
      }
    })
  })
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getJiraConfig }
}
