/**
 *
 * @param {Permission.CanAccessApp} canAccessAppParams
 * @returns boolean
 */
const canAccessApp = ({ userInfo, view, projectKey = '', dialog = '' }) => {
  const { isTimesheetPages = false, isConfigurationPage = false, isJiraIssueContent = false, isTimesheetInProjectPage = false, isTimereportsInReport = false, isGadget = false, isDialog = false, isMainTimesheetPageFromFilter = false, isWelcome = false } = view
  const { isAdmin, groups, userPermissionGroups } = userInfo

  const configuration = userInfo.configuration || {}
  const timeEntryPanelProjects = 'timeentryPanelProjects' in configuration ? configuration.timeentryPanelProjects : []
  const timeEntryPanelGroups = 'timeentryPanelGroups' in configuration ? configuration.timeentryPanelGroups : []
  const disableLogWork = 'disableLogWork' in configuration ? configuration.disableLogWork : undefined
  const hasTimeEntryPanelGroups = (isTimesheetPages || isJiraIssueContent || isTimesheetInProjectPage) && timeEntryPanelGroups && groups.some(group => timeEntryPanelGroups.includes(group))
  const hasJiraProjectPermission = timeEntryPanelProjects && timeEntryPanelProjects.includes(projectKey)
  const hasJiraIssueContentPermission = (isTimesheetInProjectPage && hasJiraProjectPermission) || (hasJiraProjectPermission && isJiraIssueContent) || hasTimeEntryPanelGroups

  if (isDialog && disableLogWork && dialog === 'createworklog') {
    return false
  }

  if (isTimereportsInReport || (isGadget && !isJiraIssueContent) || isDialog || isMainTimesheetPageFromFilter) {
    return true
  }

  if (userPermissionGroups && userPermissionGroups.includes('auditorsGroups') && isTimesheetPages) {
    return true
  }

  if (isAdmin && isConfigurationPage) {
    return true
  }

  if (isAdmin && isWelcome) {
    return true
  }

  if (hasJiraIssueContentPermission) {
    return true
  }

  return false
}

if (typeof module === 'object' && module.exports) {
  module.exports = { canAccessApp }
}
