const apRequestWithRetryOptions = (options) => {
  const start = performance.now()
  const method = (options.type || 'GET').toUpperCase()
  const url = (options.url || '').split('?')[0]

  const successBak = options.success
  const errorBak = options.error
  options.success = function (responseText, error, xhr) {
    const duration = Math.round(performance.now() - start)
    const status = xhr?.status
    if (!responseText && xhr && xhr.status === 0) {
      options.success = successBak
      options.error = errorBak
      setTimeout(function () {
        AP.request(options)
      }, 100)
      try {
        addDDRumAction(method, url, status, duration)
      } catch (_) {}
    } else {
      try {
        addDDRumAction(method, url, status, duration)
      } catch (_) {}
      successBak(responseText)
    }
  }
  options.error = function (xhr, type, error) {
    try {
      const duration = Math.round(performance.now() - start)
      const status = xhr?.status
      addDDRumAction(method, url, status, duration)
    } catch (_) {}
    if (xhr && [429, 500, 502, 503, 504].indexOf(xhr.status) >= 0 && options.retryCount > 0) {
      options.success = successBak
      options.error = errorBak
      options.retryCount--
      setTimeout(function () {
        AP.request(options)
      }, 100 * (10 - options.retryCount))
    } else if (errorBak) {
      errorBak(xhr, type, error)
    }
  }
  AP.requestBak(options)
}

function addDDRumAction (method, url, status, duration) {
  if (window.DD_RUM?.addAction) {
    window.DD_RUM.addAction('jira_rest_call', {
      method,
      url,
      status,
      baseUrl: window.baseUrl,
      ok: status >= 200 && status < 400,
      duration_ms: duration
    })
  }
}

if (typeof module === 'object' && module.exports) {
  module.exports = { apRequestWithRetryOptions }
}
