const getJiraUserMyGroups = async ({ accountId }) => {
  return new Promise((resolve) => {
    AP.request({
      url: `/rest/api/2/user?expand=groups&accountId=${accountId}`,
      cache: true,
      contentType: 'application/json',
      success: (data) => {
        const parsedData = JSON.parse(data)
        resolve(parsedData)
      }
    })
  })
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getJiraUserMyGroups }
}
