app.controller('DeleteWorkDialogController', ['$scope', '$q', 'pivottableService',
  'configurationService', '$modalInstance', 'worklogs', 'loggedInUser',
  'canDeleteOwnWorklog', 'cannotDeleteOwnWorklogIssue',
  'canDeleteAllWorklog', 'cannotDeleteAllWorklogIssue',
  function ($scope, $q, pivottableService,
    configurationService, $modalInstance, worklogs, currentUser,
    canDeleteOwnWorklog, cannotDeleteOwnWorklogIssue, canDeleteAllWorklog, cannotDeleteAllWorklogIssue) {
    $scope.cancel = function () {
      $modalInstance.dismiss()
    }

    $scope.closeDialog = function (worklogs) {
      $scope.loading = true
      worklogs.deferred = $q.defer()
      $modalInstance.close(worklogs)
      worklogs.deferred.promise.catch(function () {
        delete $scope.loading
      })
    }

    $scope.worklogs = worklogs

    configurationService.getUserConfiguration(currentUser).then(function (config) {
      worklogs.filter(wkLog => !wkLog.locked && (wkLog.ownWorklog ? canDeleteOwnWorklog && !cannotDeleteOwnWorklogIssue[wkLog.issueKey]
        : canDeleteAllWorklog && !cannotDeleteAllWorklogIssue[wkLog.issueKey])).forEach(worklog => {
        worklog.on = moment(TimesheetUtils.convertDate(worklog.started,
          !config.preserveStartedTime && worklog.author ? worklog.author.timeZone : currentUser.timeZone)).format('DD/MMM')
      })
    })

    $scope.delete = function () {
      configurationService.getUserConfiguration(currentUser).then(function (config) {
        pivottableService.clearWorklogCache(config)
      })
      $scope.closeDialog($scope.worklogs)
    }
  }
])
