const renderNoPermission = ({ isTimesheetPages, isConfigurationPage, isDialog }) => {
  const isInPage = isTimesheetPages || isConfigurationPage
  if (isInPage) {
    AP.flag.create({
      title: 'Authorization error',
      body: 'You do not have access',
      type: 'error'
    })
  }
  if (isDialog) {
    const element = document.createElement('div')
    element.style.height = '100%'
    element.innerHTML = `
      <div class="bg-gray-100" style="height: 100%; display: flex; align-items: center; justify-content: center;">
        <div class="bg-white p-6 rounded-lg shadow-lg max-w-sm text-center">
          <div style="padding: 20px;">
              <svg xmlns="http://www.w3.org/2000/svg" class="h-10 w-10 mx-auto" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M12 2a10 10 0 110 20 10 10 0 010-20z" />
              </svg>
          </div>
          <h1 class="text-2xl font-semibold mb-2">Permission denied</h1>
          <p class="text-gray-600 mb-4">You do not have permission to access this area.</p>
        </div>
      <div>
    `
    document.body.appendChild(element)
  }
}

if (typeof module === 'object' && module.exports) {
  module.exports = { renderNoPermission }
}
