const getUserInfoFromBackend = () => {
  return new Promise((resolve, reject) => {
    AP.context.getToken().then((token) => {
      fetch('/api/user/me', {
        headers: {
          Authorization: 'JWT ' + token
        },
        method: 'GET'
      }).then(response => {
        return response.json()
      }).then(data => {
        resolve(data)
      })
    })
  })
}

const getPermissionGroups = async ({ userAccountId, tenantConfigurationsGroups }) => {
  const userInfo = await getJiraUserMyGroups({ accountId: userAccountId })
  const userGroups = userInfo.groups.items.map(item => item.name)

  const byGroupsThatUserIsMember = ([_key, value]) => {
    const valueArray = Array.isArray(value) ? value : [value]
    return valueArray.some(permissionGroup => userGroups.includes(permissionGroup))
  }

  return {
    userPermissionGroups: Object.entries(tenantConfigurationsGroups)
      .filter(byGroupsThatUserIsMember)
      .map(([key]) => key),
    groups: userGroups
  }
}

const emptyUserDetail = (isAdmin) => ({
  configuration: null,
  userPermissionGroups: null,
  groups: [],
  isAdmin
})

const getUserDetails = async ({ tenantConfiguration, isAdmin }) => {
  const currentUser = await getCurrentUser()
  const userAccountId = currentUser.atlassianAccountId
  const { userPermissionGroups, groups } = await getPermissionGroups({ userAccountId, tenantConfigurationsGroups: tenantConfiguration.value })
  return {
    configuration: tenantConfiguration.value,
    userPermissionGroups: userPermissionGroups,
    groups: groups,
    isAdmin
  }
}

const getUserInfo = async () => {
  const isAdmin = await getJiraPermissionsAPI('ADMINISTER')
  const tenantConfiguration = await getUserInfoFromBackend()
  if (!tenantConfiguration.key) {
    return emptyUserDetail(isAdmin)
  }
  const userDetails = await getUserDetails({ tenantConfiguration, isAdmin })
  return userDetails
}

if (typeof module === 'object' && module.exports) {
  module.exports = { getUserInfoFromBackend, getUserInfo, getPermissionGroups }
}
