TimesheetUtils.uniqueConcat = function (array, add) {
  var a = array ? array.concat() : []
  for (var i = 0; i < add.length; i++) {
    if (a.indexOf(add[i]) < 0) {
      a.push(add[i])
    }
  }
  return a
}

