TimesheetUtils.moreFieldsForExport = function (routeParams, exportColumns, allFields) {
  var addIfNotContains = function (arr, item) {
    if (exportColumns.indexOf(item.id) === -1 && arr.indexOf(item) === -1) {
      arr.push(item)
    }
  }
  var findField = function (fieldId) {
    return TimesheetUtils.findByProperty('key', fieldId, allFields) ||
      { id: fieldId, name: fieldId }
  }
  var moreFields = []
  var field
  if (angular.isArray(routeParams.moreFields)) {
    for (var i = 0; i < routeParams.moreFields.length; i++) {
      var moreField = routeParams.moreFields[i]
      field = findField(moreField)
      addIfNotContains(moreFields, field)
    }
  } else if (routeParams.moreFields) {
    field = findField(routeParams.moreFields)
    addIfNotContains(moreFields, field)
  }
  if (routeParams.groupByField) {
    field = findField(routeParams.groupByField)
    addIfNotContains(moreFields, field)
  }
  if (routeParams.groupByField && routeParams.categorizeByField) {
    field = findField(routeParams.categorizeByField)
    addIfNotContains(moreFields, field)
  }
  return moreFields
}

TimesheetUtils.isWorklogInGroupFilter = function (worklog, users, options) {
  if (options.groups) {
    return users.some(user =>
      user.accountId === worklog.author.accountId &&
      user.groups.items.some(group => options.groups.includes(group.name))
    )
  } else {
    return true
  }
}

TimesheetUtils.isWorklogInFiltersAndPeriod = function (worklog, workDate, options) {
  if (options.workLabelsFilter &&
    (!worklog.comment || !TimesheetUtils.findOne(worklog.comment.split(/\s/), options.workLabelsFilter))) {
    return false
  }
  if (options.workAttributesFilter &&
    (!worklog.attributes || !worklog.attributes.values || !TimesheetUtils.findByCondition(attr =>
      options.workAttributesFilter.filter(attrFilter => attrFilter === '@' + attr.key + '=' + attr.value).length
    , worklog.attributes.values))) {
    return false
  }
  if (options.commentFirstWordFilter &&
    (!worklog.comment || options.commentFirstWordFilter.indexOf(worklog.comment.split(/\s/)[0].toLowerCase()) < 0)) {
    return false
  }
  if (options.startDate && workDate < options.startDate) {
    return false
  }
  if (options.endDate) {
    var endDateIncluded = TimesheetUtils.addDays(options.endDate, 1) // endDate should be in range
    if (workDate >= endDateIncluded) {
      return false
    }
  }
  return true
}

TimesheetUtils.isWorklogMatchesFilters = function (issue, worklog, workDate, options) {
  if (!TimesheetUtils.isWorklogInFiltersAndPeriod(worklog, workDate, options)) {
    return false
  }
  if (options.authors && (!worklog.author || options.authors.indexOf(worklog.author.accountId) < 0)) {
    return false
  }
  var restricted = options.restrictedProjects ? options.restrictedProjects.indexOf(worklog._issue ? worklog._issue.fields.project.key : issue.fields.project.key) >= 0 : false
  restricted = restricted && (!worklog.author || (worklog.author.accountId !== options.loggedInUser.accountId))
  return !restricted
}

// accepted by moment as ISO date, no createFromInputFallback
var dateRegex = /^\d{4}-[01]\d-[0-3]\d([\sT][0-2]\d:[0-5]\d:[0-5]\d(.\d+)?(([+-][0-2]\d:?[0-5]\d)|Z)?)?$/

if (typeof CSV !== 'undefined') {
  CSV.DETECT_TYPES = false
}
TimesheetUtils.parseTimesheetCSV = (data, jiraConfig, forUser) => {
  var rows
  try {
    rows = CSV.parse(data)
  } catch (err) {
    console.log(err)
    rows = []
  }
  return rows.map(row => {
    var worklog = row.reduce((worklog, column) => {
      var m
      if ((m = column.match(/^\w+-\d+$/g))) {
        worklog.issueKey = m[0]
      } else if ((m = column.match(dateRegex))) {
        worklog.started = moment(m[0]).toJSON()
      } else if (column.match(/^\d+(\.\d+)?$/)) {
        worklog.timeSpent = column
      } else if (TimesheetUtils.isTimespent(column)) {
        worklog.timeSpent = column
      } else if ((m = column.match(/^accountId:(.+)$/i))) {
        worklog.user = m[1]
      } else {
        worklog.comment = column
      }
      return worklog
    }, {})
    if (!worklog.started) {
      worklog.started = TimesheetUtils.adjustedDateStarted(worklog, jiraConfig).toJSON()
    }
    if (forUser && !worklog.user) {
      worklog.user = forUser
    }
    return worklog
  }).filter(w => w.issueKey && w.started && w.timeSpent)
}

