TimesheetUtils.getProgressHtml = function (value) {
  if (value.timespent + value.estimate === 0) {
    return '&nbsp;'
  } else {
    var percents = Math.round(value.timespent * 100 / (value.estimate + value.timespent)) // calcColumnFunction(row);
    var rightPercents = 100 - percents
    var rightColor = 'bar-blank'
    var leftColor = 'bar-green'

    if (rightPercents === 0) rightColor = leftColor
    if (percents >= 20 && percents <= 50) leftColor = 'bar-yellow'
    if (percents <= 20) leftColor = 'bar-red'

    var html = `
      <table cellpadding="0" cellspacing="0" border="0" class="ml-3">
        <tr>
          <td style="padding: 0; margin: 0">
            <table border="0" style="font-size: 8px; width: 90px" cellpadding="0" cellspacing="0">
              <tr>
                <td style="width:${percents + 5}%; padding: 0">
                  <span style="padding-left: 100%"
                        class="bg-${leftColor}
                               border-solid rounded-l-3xl
                               border-b border-l border-t border-r-0
                               border-text-divider-color-3">
                    &nbsp;
                  </span>
                </td>
                <td style="width:${rightPercents}%; padding: 0">
                  <span style="padding-left: 100%"
                        class="bg-${rightColor}
                               border-solid rounded-r-3xl
                               border-b border-r border-t border-l-0
                               border-text-divider-color-3">
                    &nbsp;
                  </span>
                </td>
              </tr>
            </table>
          </td>
          <td style="margin: 0; padding: 0 0 0 10px">
            ${percents}%
          </td>
        </tr>
      </table>`

    return html
  }
}

TimesheetUtils.getOriginalEstimateRemainingHtml = function (column, jiraConfig) {
  var lozenge = 'aui-lozenge'
  var estimate
  if (column.issue) { // details entry
    if (!column.issue.fields.resolution) {
      lozenge += ' aui-lozenge-subtle'
    }
    estimate = column.issue.fields.timeoriginalestimate
  } else {
    estimate = 0
    for (var i = 0; i < column.entries.length; i++) {
      var issue = column.entries[i].rowKey.issue || column.entries[i].rowKey._issue
      if (!issue.fields.resolution) {
        lozenge += ' aui-lozenge-subtle'
      }
      estimate += issue.fields.timeoriginalestimate
    }
  }
  var value = typeof column.value === 'object' ? column.value.value : column.value
  if (value < 0) {
    var percents = Math.round(-value * 100 / estimate)
    lozenge += percents > 50 ? ' aui-lozenge-error' : ' aui-lozenge-current'
  } else {
    lozenge += ' aui-lozenge-success'
  }
  var prettyHours = DrawHelper.getFormattedTime(value, jiraConfig)
  var html = value ? '<div class="' + lozenge + '">' + prettyHours + '</div>' : '&nbsp;'
  return html
}

TimesheetUtils.processFields = function (data, options) {
  return data.filter(field => {
    if (field.untranslatedName === 'Original Estimate' && field.custom && field.scope && field.scope.type === 'PROJECT') {
      if (!options.customOriginalEstimates) {
        options.customOriginalEstimates = []
      }
      options.customOriginalEstimates.push(field.id)
      return false
    } else {
      return true
    }
  })
}
